import json,urllib.request,concurrent.futures
x=json.load(open('rs34562254-assoc.json'))['_embedded']['associations']
def f(a):
 aid=a['_links']['self']['href'].rstrip('/').split('/')[-1]
 try:
  d=json.load(urllib.request.urlopen(f'https://www.ebi.ac.uk/gwas/rest/api/associations/{aid}/study',timeout=15)); pub=d.get('publicationInfo') or {}
  return (a.get('pvalue') or 0,aid,d.get('accessionId'),pub.get('pubmedId'),d.get('diseaseTrait',{}).get('trait'))
 except: return None
out=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=15) as ex:
 for z in ex.map(f,x):
  if z: out.append(z)
for z in sorted(out):
 p=z[0]
 if (1e-18<=p<=1e-14) or any(k in (z[4] or '').lower() for k in ['immun','igg','protein','antibod','cell']): print('\\t'.join(map(str,z)))
print('total',len(out),flush=True)
PY"

